public boolean shouldPrintMessage(int timestamp, String message) {
    // Assuming a data structure like Map<String, Integer> to store the last printed timestamp for each message
    Map<String, Integer> messageTimestamps = new HashMap<>();

    // Check if the message has been printed before and if the current timestamp is more than 10 seconds after the last print
    if (messageTimestamps.containsKey(message)) {
        int lastPrintedTimestamp = messageTimestamps.get(message);
        if (timestamp - lastPrintedTimestamp < 10) {
            return false; // Message should not be printed
        }
    }

    // Update the last printed timestamp for the message
    messageTimestamps.put(message, timestamp);
    return true; // Message should be printed
}

