private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        K currentKey = keys.get(i);
        int lowerBound = -1; // Default value if no lower bound is found
        for (int j = i - 1; j >= 0; j--) {
            K previousKey = keys.get(j);
            if (previousKey.compareTo(currentKey) < 0) {
                lowerBound = previousKey.hashCode(); // Assuming hashCode is used as the lower bound value
                break;
            }
        }
        lowerBounds.add(lowerBound);
    }
    return lowerBounds;
}

