    while (bb.hasRemaining()) {
        byte b = bb.get();
        if ((b & 0x80) == 0) {
            // Single-byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // Two-byte character
            byte b2 = bb.get();
            sb.append((char) (((b & 0x1F) << 6) | (b2 & 0x3F)));
            i += 2;
        } else if ((b & 0xF0) == 0xE0) {
            // Three-byte character
            byte b2 = bb.get();
            byte b3 = bb.get();
            sb.append((char) (((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F)));
            i += 3;
